function bindNav(){
  const route=location.hash.replace(/^#/,'').split('/')[0]||'home';
  document.querySelectorAll('.nav [data-go]').forEach(b=>{const active=b.dataset.go===route||(route==='class'&&b.dataset.go==='classes')||(route.startsWith('admin-')&&b.dataset.go==='admin');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
  const toggle=$('.menu-toggle'),nav=$('#mainNav');if(toggle&&nav)toggle.onclick=()=>{const expanded=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(expanded));nav.classList.toggle('menu-open',expanded)};
const os=$('#orgSwitcher');if(os)os.onchange=()=>{state.organizationId=os.value;storageSet('slc_org',os.value);location.reload()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.go});$('[data-logout]')?.addEventListener('click',async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});state.user=null;state.activeExam=null;state.organizations=[];_apiCache.clear();location.hash='login';render()})}

