async function adminAssessmentCenter(){
  const initialTab=arguments[0]||'overview';
  if(!['super_admin','school_admin','account_admin'].includes(state.user?.role||'')&&!arr(state.user?.permissions).includes('assessment.view')){slcNotice('Không có quyền','Tài khoản chưa được cấp quyền assessment.view.');return}
  let j;try{j=await api('/api/admin/assessment-center',{cacheTtl:0})}catch(e){slcNotice('Không tải được Trung tâm Đánh giá',e.message);return}
  let classes=[];try{classes=arr((await api('/api/admin/classes',{cacheTtl:0})).classes)}catch{}
  const exams=arr(j.exams),now=Date.now(),timeMs=v=>{if(!v)return null;const d=safeDate(v);return d?d.getTime():null},effective=x=>{if(x.status==='draft')return {key:'draft',label:'Bản nháp'};if(x.status==='review')return {key:'scheduled',label:'Chờ duyệt'};if(x.status==='approved')return {key:'scheduled',label:'Đã duyệt'};if(x.status==='closed')return {key:'closed',label:'Đã đóng'};if(x.status==='archived')return {key:'archived',label:'Lưu trữ'};const o=timeMs(x.opens_at),c=timeMs(x.closes_at);if(o&&now<o)return {key:'scheduled',label:'Đã lên lịch'};if(c&&now>c)return {key:'ended',label:'Đã hết lịch'};return {key:'open',label:'Đang mở'}},fmt=v=>v?formatDateTime(v):'Không giới hạn';
  const openCount=exams.filter(x=>effective(x).key==='open').length;
  const tabs=[['overview','Tổng quan'],['exams','Kỳ thi'],['bank',`Ngân hàng câu hỏi · ${Number(j.question_bank_count||0)}`],['candidates','Người dự thi'],['live','Giám sát trực tiếp'],['attempts','Lượt thi'],['grading',`Chấm bài · ${Number(j.pending_grades||0)}`],['rubrics','Rubric'],['results','Kết quả'],['appeals','Phúc khảo'],['incidents','Sự cố'],['email','Email'],['audit','Nhật ký'],['settings','Cấu hình']];
  app.innerHTML=shell(`<section class="assessment-admin-hero"><div><div class="eyebrow">SKY FIRST ASSESSMENT CENTER · QUẢN TRỊ</div><h1>Trung tâm Đánh giá</h1><p>Kỳ thi, ngân hàng câu hỏi, người dự thi, chấm tự luận và nhật ký đều hoạt động trong cùng một trung tâm.</p></div><div class="assessment-admin-actions"><button class="btn" data-go="admin">← Control Center</button><select id="adminAssessmentClass">${classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><button class="btn primary" id="adminCreateAssessment">+ Tạo kỳ thi</button></div></section><nav class="assessment-admin-nav">${tabs.map(([k,l])=>`<button data-assessment-tab="${k}" class="${k===initialTab?'active':''}">${esc(l)}</button>`).join('')}</nav><section id="assessmentAdminBody"></section>`);bindNav();$('#adminCreateAssessment')?.addEventListener('click',()=>{const id=$('#adminAssessmentClass')?.value;if(!id)return slcNotice('Thông báo','Chưa có lớp để gắn kỳ thi.');openExamBuilder(id,true)});
  const examList=()=>`<section class="assessment-admin-list">${exams.map(x=>{const n=Number(x.internal_attempts||0)+Number(x.guest_attempts||0),a=Number(x.active_internal||0)+Number(x.active_guest||0),st=effective(x);return `<article class="assessment-row"><div class="assessment-row-main"><div class="assessment-row-tags"><span class="assessment-type">${esc(x.assessment_label||'Đánh giá')}</span><span class="assessment-status ${st.key}"><i></i>${esc(st.label)}</span></div><h3>${esc(x.title)}</h3><div class="assessment-meta"><span>🏫 ${esc(x.class_name)}</span><span>⏱ ${x.time_limit_enabled===0?'Không giới hạn':Number(x.duration_minutes||0)+' phút'}</span><span>👥 ${n} lượt</span><span>● ${a} đang thi</span>${x.require_email_verify?'<span>✉ Xác minh email</span>':''}</div><div class="assessment-schedule"><div><small>MỞ TỪ</small><b>${esc(fmt(x.opens_at))}</b></div><div><small>ĐÓNG LÚC</small><b>${esc(fmt(x.closes_at))}</b></div></div></div><div class="assessment-row-actions"><button class="btn" data-admin-monitor="${x.id}">Giám sát</button>${x.status==='draft'?`<button class="btn" data-admin-sections="${x.id}">Cấu trúc đề</button>`:''}${x.public_access&&x.public_token?`<button class="btn" data-admin-copy="${x.public_token}">Sao chép link</button>`:''}${x.result_policy==='publish_later'?`<button class="btn" data-admin-publish-results="${x.id}">Công bố kết quả</button>`:''}${x.status==='draft'?`<button class="btn primary" data-admin-status="${x.id}" data-status="review">Gửi duyệt</button>`:x.status==='review'?`<button class="btn primary" data-admin-status="${x.id}" data-status="approved">Duyệt</button>`:x.status==='approved'?`<button class="btn primary" data-admin-status="${x.id}" data-status="published">Công bố</button>`:x.status==='published'&&st.key==='scheduled'?`<button class="btn primary" data-admin-force-open="${x.id}">Mở ngay</button>`:st.key==='open'?`<button class="btn" data-admin-status="${x.id}" data-status="closed">Đóng kỳ thi</button>`:''}<button class="btn danger" data-admin-delete="${x.id}">Xóa/Lưu trữ</button></div></article>`}).join('')||'<div class="empty-state">Chưa có hoạt động đánh giá.</div>'}</section>`;
  const bindExamActions=()=>{document.querySelectorAll('[data-admin-force-open]').forEach(b=>b.onclick=async()=>{if(!await slcConfirm('Mở kỳ thi ngay','Lịch mở/đóng hiện tại sẽ được gỡ để kỳ thi có hiệu lực ngay.','Mở ngay'))return;await api(`/api/exams/${b.dataset.adminForceOpen}`,{method:'PATCH',body:JSON.stringify({force_open:true})});adminAssessmentCenter('exams')});document.querySelectorAll('[data-admin-monitor]').forEach(b=>b.onclick=()=>adminExamAttempts(b.dataset.adminMonitor));document.querySelectorAll('[data-admin-sections]').forEach(b=>b.onclick=()=>adminAssessmentSections(b.dataset.adminSections));document.querySelectorAll('[data-admin-copy]').forEach(b=>b.onclick=async()=>{const u=`https://exam.skyfirst.io.vn/join/${encodeURIComponent(b.dataset.adminCopy)}`;try{await navigator.clipboard.writeText(u);slcNotice('Đã sao chép','Link dự thi đã được sao chép.')}catch{await slcCopyText('Sao chép link dự thi',u)}});document.querySelectorAll('[data-admin-publish-results]').forEach(b=>b.onclick=async()=>{if(!await slcConfirm('Công bố kết quả','Người dự thi sẽ thấy điểm theo chính sách kết quả.','Công bố'))return;await api(`/api/exams/${b.dataset.adminPublishResults}`,{method:'PATCH',body:JSON.stringify({publish_results:true})});adminAssessmentCenter('exams')});document.querySelectorAll('[data-admin-status]').forEach(b=>b.onclick=async()=>{const s=b.dataset.status,label={review:'Gửi duyệt',approved:'Duyệt kỳ thi',published:'Công bố kỳ thi',closed:'Đóng kỳ thi'}[s]||'Đổi trạng thái';if(!await slcConfirm(label,'Thay đổi này được ghi vào nhật ký kiểm toán và áp dụng theo vòng đời kỳ đánh giá.',label))return;await api(`/api/exams/${b.dataset.adminStatus}`,{method:'PATCH',body:JSON.stringify({status:s})});adminAssessmentCenter('exams')});document.querySelectorAll('[data-admin-delete]').forEach(b=>b.onclick=async()=>{if(!await slcConfirm('Xóa hoặc lưu trữ','Kỳ thi có lượt dự thi sẽ được lưu trữ.','Tiếp tục'))return;await api(`/api/exams/${b.dataset.adminDelete}`,{method:'DELETE'});adminAssessmentCenter('exams')})};
  const renderTab=async tab=>{document.querySelectorAll('[data-assessment-tab]').forEach(b=>b.classList.toggle('active',b.dataset.assessmentTab===tab));const root=$('#assessmentAdminBody');if(tab==='overview'){const active=exams.reduce((n,x)=>n+Number(x.active_internal||0)+Number(x.active_guest||0),0),attempts=exams.reduce((n,x)=>n+Number(x.internal_attempts||0)+Number(x.guest_attempts||0),0);root.innerHTML=`<section class="assessment-kpis"><article><span>Hoạt động</span><b>${exams.length}</b><small>trong tổ chức hiện tại</small></article><article><span>Đang mở</span><b>${openCount}</b><small>đã tính lịch</small></article><article><span>Đang thi</span><b>${active}</b><small>phiên đang hoạt động</small></article><article><span>Tổng lượt</span><b>${attempts}</b><small>nội bộ + khách</small></article></section>${examList()}`;bindExamActions();return}if(tab==='exams'){root.innerHTML=`<section class="assessment-admin-panel"><div class="assessment-panel-head"><div><h2>Danh sách kỳ thi</h2><p>Quản lý trạng thái, lịch, link dự thi và kết quả.</p></div></div>${examList()}</section>`;bindExamActions();return}if(tab==='bank'){const r=await api('/api/admin/assessment-question-bank',{cacheTtl:0});root.innerHTML=`<section class="card full"><div class="toolbar" style="justify-content:space-between"><div><h2>Ngân hàng câu hỏi</h2><p class="muted">Câu hỏi dùng lại được theo tổ chức.</p></div>${state.user?.role!=='account_admin'?'<button class="btn primary" id="bankAdd">+ Thêm câu hỏi</button>':''}</div><div class="list">${arr(r.questions).map(q=>`<div class="item"><b>${esc(q.question)}</b><div class="muted">${esc(q.type)} · ${Number(q.points||1)} điểm · ${esc(q.difficulty||'medium')} · ${esc(q.status||'draft')}</div>${state.user?.role!=='account_admin'?`<div class="toolbar"><button class="btn" data-bank-edit="${q.id}">Sửa</button>${q.status==='draft'?`<button class="btn" data-bank-status="${q.id}" data-status="review">Gửi duyệt</button>`:q.status==='review'?`<button class="btn" data-bank-status="${q.id}" data-status="approved">Duyệt</button>`:q.status==='approved'?`<button class="btn" data-bank-status="${q.id}" data-status="active">Kích hoạt</button>`:q.status==='active'?`<button class="btn" data-bank-status="${q.id}" data-status="retired">Ngừng dùng</button>`:''}<button class="btn danger" data-bank-delete="${q.id}">Xóa</button></div>`:''}</div>`).join('')||'<div class="muted">Chưa có câu hỏi.</div>'}</div></section>`;$('#bankAdd')?.addEventListener('click',async()=>{const form=await slcForm('Thêm câu hỏi vào ngân hàng','Tạo câu hỏi dùng lại cho các kỳ đánh giá.',[{name:'question',label:'Nội dung câu hỏi',type:'textarea',required:true},{name:'type',label:'Dạng câu hỏi',type:'select',value:'short',options:[{value:'mcq',label:'Một đáp án'},{value:'multi',label:'Nhiều đáp án'},{value:'truefalse',label:'Đúng / Sai'},{value:'matching',label:'Ghép cặp'},{value:'ordering',label:'Sắp xếp'},{value:'fill',label:'Điền khuyết'},{value:'short',label:'Trả lời ngắn'},{value:'numeric',label:'Số'},{value:'math',label:'Toán / công thức'},{value:'essay',label:'Tự luận'},{value:'long',label:'Bài viết dài'},{value:'structured',label:'Trả lời có cấu trúc'},{value:'file',label:'Nộp tệp'},{value:'image',label:'Nộp ảnh'},{value:'audio',label:'Nộp âm thanh'}]},{name:'answer',label:'Đáp án / dữ liệu đáp án',type:'textarea',placeholder:'Có thể để trống với câu tự luận'},{name:'points',label:'Điểm',type:'number',value:'1',min:.25,step:.25,required:true}],'Thêm câu hỏi');if(!form?.question)return;await api('/api/admin/assessment-question-bank',{method:'POST',body:JSON.stringify({question:form.question,type:form.type,answer:form.answer||'',points:Math.max(.25,Number(form.points)||1)})});renderTab('bank')});document.querySelectorAll('[data-bank-edit]').forEach(b=>b.onclick=async()=>{const q=arr(r.questions).find(x=>x.id===b.dataset.bankEdit);if(!q)return;const form=await slcForm('Sửa câu hỏi','Cập nhật nội dung và đáp án.',[{name:'question',label:'Nội dung câu hỏi',type:'textarea',value:q.question||'',required:true},{name:'answer',label:'Đáp án / dữ liệu đáp án',type:'textarea',value:typeof q.answer==='string'?q.answer:JSON.stringify(q.answer??'')}],'Lưu');if(!form?.question)return;await api(`/api/admin/assessment-question-bank/${b.dataset.bankEdit}`,{method:'PATCH',body:JSON.stringify(form)});renderTab('bank')});document.querySelectorAll('[data-bank-status]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/assessment-question-bank/${b.dataset.bankStatus}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});renderTab('bank')});document.querySelectorAll('[data-bank-delete]').forEach(b=>b.onclick=async()=>{if(!await slcConfirm('Xóa câu hỏi','Câu hỏi sẽ bị xóa khỏi ngân hàng.','Xóa'))return;await api(`/api/admin/assessment-question-bank/${b.dataset.bankDelete}`,{method:'DELETE'});renderTab('bank')});return}if(['candidates','live','attempts'].includes(tab)){const r=await api('/api/admin/assessment-candidates',{cacheTtl:0}),rows=tab==='live'?arr(r.candidates).filter(x=>x.status==='in_progress'):arr(r.candidates);root.innerHTML=`<section class="card full table-wrap"><h2>${tab==='live'?'Giám sát trực tiếp':tab==='attempts'?'Toàn bộ lượt thi':'Người dự thi'}</h2><table class="learning-table"><thead><tr><th>Thí sinh</th><th>Kỳ thi</th><th>Nguồn</th><th>Trạng thái</th><th>Bắt đầu</th><th>Điểm</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><div class="muted">${esc(x.email||'')} · ${esc(x.candidate_code||'')}</div></td><td>${esc(x.exam_title)}</td><td>${esc(x.source)}</td><td>${esc(x.status)}</td><td>${esc(x.started_at||'—')}</td><td>${x.score==null?'—':`${x.score}/${x.max_score||'—'}`}</td></tr>`).join('')||'<tr><td colspan="6">Không có dữ liệu.</td></tr>'}</tbody></table></section>`;return}if(tab==='grading'){const r=await api('/api/admin/assessment-manual-grading',{cacheTtl:0});root.innerHTML=`<section class="card full"><h2>Chấm tự luận</h2><div class="list">${arr(r.items).map(x=>`<article class="item"><b>${esc(x.candidate_name)} · ${esc(x.exam_title)}</b><p>${esc(x.question)}</p><div class="notice">Bài làm: ${esc(typeof x.answer==='object'?JSON.stringify(x.answer):x.answer||'—')}</div><div class="muted">Tối đa ${x.points} điểm · ${x.status==='published'?'Đã công bố':'Chờ chấm'}</div>${state.user?.role!=='account_admin'?`<button class="btn primary" data-manual-grade="${x.id}">Chấm / sửa điểm</button>`:''}</article>`).join('')||'<div class="muted">Không có câu tự luận chờ chấm.</div>'}</div></section>`;document.querySelectorAll('[data-manual-grade]').forEach(b=>b.onclick=async()=>{const x=arr(r.items).find(i=>i.id===b.dataset.manualGrade);if(!x)return;const form=await slcForm('Chấm câu tự luận',`Điểm tối đa: ${x.points}`,[{name:'score',label:'Điểm',type:'number',value:x.score??'',min:0,max:x.points,step:.25,required:true},{name:'feedback',label:'Nhận xét',type:'textarea',value:x.feedback||''}],'Lưu và công bố');if(!form)return;await api(`/api/admin/assessment-manual-grading/${x.id}`,{method:'PATCH',body:JSON.stringify({score:Number(form.score),feedback:form.feedback||'',publish:true})});renderTab('grading')});return}if(tab==='rubrics'){const r=await api('/api/admin/assessment-rubrics',{cacheTtl:0});root.innerHTML=`<section class="card full"><div class="toolbar" style="justify-content:space-between"><div><h2>Thư viện Rubric</h2><p class="muted">Rubric dùng lại cho tự luận, bài viết, project và assignment. Mỗi lần sửa tiêu chí tạo phiên bản mới.</p></div><button class="btn primary" id="rubricAdd">+ Tạo rubric</button></div><div class="list">${arr(r.rubrics).map(x=>`<article class="item"><b>${esc(x.name)} · v${Number(x.current_version||1)}</b><div class="muted">${esc(x.description||'')} · ${arr(x.criteria).length} tiêu chí · ${esc(x.status||'active')}</div></article>`).join('')||'<div class="muted">Chưa có rubric.</div>'}</div></section>`;$('#rubricAdd')?.addEventListener('click',async()=>{const form=await slcForm('Tạo rubric','Nhập mỗi tiêu chí trên một dòng theo mẫu: Tên tiêu chí | điểm tối đa | mô tả.',[{name:'name',label:'Tên rubric',required:true},{name:'description',label:'Mô tả',type:'textarea'},{name:'criteria',label:'Tiêu chí',type:'textarea',required:true,placeholder:'Lập luận | 4 | Rõ ràng và có dẫn chứng\nDiễn đạt | 2 | Mạch lạc, chính xác'}],'Tạo rubric');if(!form?.name)return;const criteria=String(form.criteria||'').split(/\n+/).map((line,i)=>{const [name,max_score,description]=line.split('|').map(x=>x.trim());return name?{id:`c${i+1}`,name,max_score:Math.max(.25,Number(max_score)||1),description:description||''}:null}).filter(Boolean);if(!criteria.length)return slcNotice('Rubric','Cần ít nhất một tiêu chí.');await api('/api/admin/assessment-rubrics',{method:'POST',body:JSON.stringify({name:form.name,description:form.description||'',criteria})});renderTab('rubrics')});return}if(tab==='results'){const r=await api('/api/admin/assessment-results',{cacheTtl:0});root.innerHTML=`<section class="card full table-wrap"><h2>Vòng đời kết quả</h2><p class="muted">ĐÃ NỘP → ĐANG CHẤM → ĐÃ CHẤM → CHỜ DUYỆT → ĐÃ DUYỆT → ĐÃ CÔNG BỐ → KẾT QUẢ CUỐI.</p><table class="learning-table"><thead><tr><th>Thí sinh</th><th>Kỳ thi</th><th>Điểm</th><th>Trạng thái</th><th>Xử lý</th></tr></thead><tbody>${arr(r.results).map(x=>`<tr><td><b>${esc(x.candidate_name||'—')}</b><div class="muted">${esc(x.candidate_code||'')}</div></td><td>${esc(x.exam_title||'—')}</td><td>${x.score==null?'—':`${x.score}/${x.max_score??'—'}`}</td><td><span class="pill">${esc(x.state)}</span></td><td>${['graded','appeal'].includes(x.state)?`<button class="btn" data-result-action="approve" data-result-id="${x.attempt_id}">Duyệt</button>`:x.state==='approved'?`<button class="btn primary" data-result-action="publish" data-result-id="${x.attempt_id}">Công bố</button>`:x.state==='published'?`<button class="btn" data-result-action="final" data-result-id="${x.attempt_id}">Chốt cuối</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có kết quả.</td></tr>'}</tbody></table></section>`;document.querySelectorAll('[data-result-action]').forEach(b=>b.onclick=async()=>{const reason=await slcTextInput('Xử lý kết quả','Mọi thao tác duyệt/công bố/chốt kết quả phải có lý do và được audit.','Lý do');if(!reason)return;await api(`/api/admin/assessment-results/${b.dataset.resultId}`,{method:'PATCH',body:JSON.stringify({action:b.dataset.resultAction,reason})});renderTab('results')});return}if(tab==='incidents'){const r=await api('/api/admin/assessment-incidents',{cacheTtl:0});root.innerHTML=`<section class="card full"><h2>Exam Incident</h2><p class="muted">Sự cố được xử lý trong hệ thống; quyết định không làm mất lịch sử.</p><div class="list">${arr(r.incidents).map(x=>`<article class="item"><b>${esc(x.exam_title)} · ${esc(x.category||'system')}</b><p>${esc(x.detail||'')}</p><div class="muted">${esc(x.severity)} · ${esc(x.status)} · ${esc(x.created_at||'')}</div>${x.status==='open'?`<button class="btn" data-incident="${x.id}">Xử lý</button>`:''}</article>`).join('')||'<div class="muted">Không có sự cố được ghi nhận.</div>'}</div></section>`;document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=async()=>{const form=await slcForm('Xử lý sự cố','Mọi quyết định phải có kết luận để lưu audit.',[{name:'decision',label:'Quyết định',type:'select',value:'no_action',options:[{value:'no_action',label:'Không hành động'},{value:'add_time',label:'Cộng giờ'},{value:'reopen',label:'Mở lại'},{value:'retake',label:'Thi lại'},{value:'invalidate',label:'Hủy kết quả'}]},{name:'minutes',label:'Số phút cộng (nếu chọn Cộng giờ)',type:'number',value:'15',min:1,max:720},{name:'resolution',label:'Kết luận / lý do',type:'textarea',required:true}],'Xác nhận');if(!form?.resolution)return;const minutes=form.decision==='add_time'?Math.max(1,Math.min(720,Number(form.minutes)||15)):0;await api(`/api/admin/assessment-incidents/${b.dataset.incident}`,{method:'PATCH',body:JSON.stringify({decision:form.decision,resolution:form.resolution,minutes})});renderTab('incidents')});return}if(tab==='appeals'){const r=await api('/api/admin/assessment-appeals',{cacheTtl:0});root.innerHTML=`<section class="card full"><h2>Phúc khảo</h2><div class="list">${arr(r.appeals).map(x=>`<article class="item"><b>${esc(x.candidate_name)} · ${esc(x.exam_title)}</b><p>${esc(x.reason)}</p><div class="muted">${esc(x.status)} · ${esc(x.created_at)}</div>${['open','reviewing'].includes(x.status)?`<div class="toolbar"><button class="btn" data-appeal-review="${x.id}">Đang xem xét</button><button class="btn primary" data-appeal-resolve="${x.id}">Giải quyết</button><button class="btn danger" data-appeal-reject="${x.id}">Từ chối</button></div>`:`<div class="notice">${esc(x.resolution||'Đã xử lý')}</div>`}</article>`).join('')||'<div class="muted">Không có yêu cầu phúc khảo.</div>'}</div></section>`;const act=async(id,status)=>{let resolution='';if(status!=='reviewing'){resolution=await slcTextInput(status==='resolved'?'Giải quyết phúc khảo':'Từ chối phúc khảo','Nhập nội dung phản hồi sẽ được lưu cùng yêu cầu.','Nội dung xử lý');if(!resolution)return}await api(`/api/admin/assessment-appeals/${id}`,{method:'PATCH',body:JSON.stringify({status,resolution})});renderTab('appeals')};document.querySelectorAll('[data-appeal-review]').forEach(b=>b.onclick=()=>act(b.dataset.appealReview,'reviewing'));document.querySelectorAll('[data-appeal-resolve]').forEach(b=>b.onclick=()=>act(b.dataset.appealResolve,'resolved'));document.querySelectorAll('[data-appeal-reject]').forEach(b=>b.onclick=()=>act(b.dataset.appealReject,'rejected'));return}if(tab==='audit'){const r=await api('/api/admin/assessment-audit',{cacheTtl:0});root.innerHTML=`<section class="card full"><h2>Nhật ký đánh giá</h2><div class="list">${arr(r.events).map(x=>`<div class="item"><b>${esc(x.event_type)}</b> · ${esc(x.exam_title)}<div class="muted">${esc(x.created_at)} · Lượt thi ${esc(x.attempt_id||'—')}</div></div>`).join('')||'<div class="muted">Chưa có sự kiện.</div>'}</div></section>`;return}if(tab==='email'){root.innerHTML=`<section class="card full"><h2>Email đánh giá</h2><p>Luồng email đang hoạt động cho: xác minh email bằng mã 6 số, xác nhận bắt đầu dự thi và xác nhận nộp bài. Email được gửi tự động từ hệ thống; mã xác minh hết hạn sau 10 phút.</p><div class="notice">Bật “Xác minh email trước khi dự thi bằng link” trong trình tạo kỳ thi để yêu cầu mã xác minh.</div></section>`;return}root.innerHTML=`<section class="card full"><h2>Cấu hình Trung tâm Đánh giá</h2><p class="muted">Các chính sách thời gian, xáo đề, toàn màn hình, đóng phiên, công bố điểm và xác minh email được cấu hình riêng trên từng kỳ thi. Quyền dữ liệu được giới hạn theo tổ chức hiện tại.</p><div class="notice">Ngân hàng câu hỏi: ${Number(j.question_bank_count||0)} · Chờ chấm tự luận: ${Number(j.pending_grades||0)} · Sự cố ghi nhận: ${Number(j.incidents||0)}</div></section>`};
  document.querySelectorAll('[data-assessment-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.assessmentTab).catch(e=>slcNotice('Không tải được mục',e.message)));await renderTab(initialTab);
}


async function publicAssessmentInvite(token){
 const safe=String(token||'').trim();
 if(!safe){slcNotice('Liên kết không hợp lệ','Thiếu mã dự thi.');return}
 location.replace(`https://exam.skyfirst.io.vn/join/${encodeURIComponent(safe)}`)
}
async function resumeGuestExam(attemptId){slcNotice('Phiên thi đã được chuyển','Bài thi khách hiện được thực hiện tại exam.skyfirst.io.vn. Vui lòng mở lại liên kết dự thi đã được giáo viên cung cấp.')}

async function launchExamDomain(attemptId){const x=await api(`/api/exam-attempts/${attemptId}/launch`,{method:'POST',body:'{}'});if(!x?.launch_url)throw new Error('Không tạo được liên kết dự thi.');location.href=x.launch_url}
async function startExam(id){const yes=await slcConfirm('Bắt đầu bài đánh giá','Khi bắt đầu, bạn sẽ được chuyển đến Trung tâm Dự thi Sky First. Tiến trình và kết quả bài làm được ghi nhận tự động.','Bắt đầu');if(!yes)return;try{const r=await api(`/api/exams/${id}/start`,{method:'POST',body:'{}'});await launchExamDomain(r.attempt_id)}catch(e){slcNotice('Không thể bắt đầu',e.message||'Vui lòng thử lại.')}}
function slcConfirm(title,message,okText='Đồng ý'){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='slc-modal-backdrop';wrap.innerHTML=`<section class="slc-modal"><h2>${esc(title)}</h2><p>${esc(message)}</p><div class="toolbar"><button class="btn" data-no>Hủy</button><button class="btn primary" data-yes>${esc(okText)}</button></div></section>`;document.body.appendChild(wrap);const done=v=>{wrap.remove();resolve(v)};wrap.querySelector('[data-no]').onclick=()=>done(false);wrap.querySelector('[data-yes]').onclick=()=>done(true)})}
function slcTextInput(title,message,placeholder=''){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='slc-modal-backdrop';wrap.innerHTML=`<section class="slc-modal"><h2>${esc(title)}</h2><p>${esc(message)}</p><div class="field"><textarea data-value placeholder="${esc(placeholder)}" maxlength="500"></textarea></div><div class="toolbar"><button class="btn" data-no>Hủy</button><button class="btn primary" data-yes>Xác nhận</button></div></section>`;document.body.appendChild(wrap);const done=v=>{wrap.remove();resolve(v)};wrap.querySelector('[data-no]').onclick=()=>done('');wrap.querySelector('[data-yes]').onclick=()=>done(wrap.querySelector('[data-value]').value.trim());wrap.querySelector('[data-value]').focus()})}
function slcForm(title,message,fields=[],okText='Xác nhận'){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='slc-modal-backdrop';const fieldHtml=fields.map(f=>{const name=esc(f.name),label=esc(f.label||f.name),value=esc(f.value??''),required=f.required?' required':'',min=f.min!=null?` min="${esc(f.min)}"`:'',max=f.max!=null?` max="${esc(f.max)}"`:'',step=f.step!=null?` step="${esc(f.step)}"`:'';if(f.type==='textarea')return `<div class="field"><label>${label}</label><textarea name="${name}"${required} placeholder="${esc(f.placeholder||'')}">${value}</textarea></div>`;if(f.type==='select')return `<div class="field"><label>${label}</label><select name="${name}"${required}>${(f.options||[]).map(o=>{const v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}"${String(v)===String(f.value??'')?' selected':''}>${esc(l)}</option>`}).join('')}</select></div>`;if(f.type==='checkbox')return `<label class="notice consent"><input type="checkbox" name="${name}"${f.value?' checked':''}> ${label}</label>`;if(f.type==='file')return `<div class="field"><label>${label}</label><input name="${name}" type="file"${required}${f.accept?` accept="${esc(f.accept)}"`:''}><small class="muted">${esc(f.help||'')}</small></div>`;return `<div class="field"><label>${label}</label><input name="${name}" type="${esc(f.type||'text')}" value="${value}" placeholder="${esc(f.placeholder||'')}"${required}${min}${max}${step}></div>`}).join('');wrap.innerHTML=`<section class="slc-modal slc-form-modal"><form data-form><h2>${esc(title)}</h2>${message?`<p>${esc(message)}</p>`:''}<div class="slc-form-fields">${fieldHtml}</div><div class="toolbar"><button type="button" class="btn" data-no>Hủy</button><button class="btn primary" type="submit">${esc(okText)}</button></div></form></section>`;document.body.appendChild(wrap);const done=v=>{wrap.remove();resolve(v)};wrap.querySelector('[data-no]').onclick=()=>done(null);wrap.querySelector('[data-form]').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),out={};for(const f of fields){if(f.type==='checkbox')out[f.name]=!!e.currentTarget.elements[f.name]?.checked;else if(f.type==='file')out[f.name]=e.currentTarget.elements[f.name]?.files?.[0]||null;else out[f.name]=String(fd.get(f.name)??'').trim()}done(out)};wrap.querySelector('input,textarea,select')?.focus()})}
function slcCopyText(title,value){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='slc-modal-backdrop';wrap.innerHTML=`<section class="slc-modal"><h2>${esc(title)}</h2><p class="muted">Nếu trình duyệt không tự sao chép, hãy chọn nội dung bên dưới.</p><div class="field"><input data-copy readonly value="${esc(value)}"></div><div class="toolbar"><button class="btn" data-close>Đóng</button><button class="btn primary" data-copy-btn>Sao chép</button></div></section>`;document.body.appendChild(wrap);const input=wrap.querySelector('[data-copy]');input.focus();input.select();wrap.querySelector('[data-close]').onclick=()=>{wrap.remove();resolve(false)};wrap.querySelector('[data-copy-btn]').onclick=async()=>{try{await navigator.clipboard.writeText(value);wrap.remove();resolve(true)}catch{input.focus();input.select()}}})}

function slcNotice(title,message){const wrap=document.createElement('div');wrap.className='slc-modal-backdrop';wrap.innerHTML=`<section class="slc-modal"><h2>${esc(title)}</h2><p>${esc(message)}</p><button class="btn primary" data-ok>Đóng</button></section>`;document.body.appendChild(wrap);wrap.querySelector('[data-ok]').onclick=()=>wrap.remove()}
async function resumeExam(attemptId){try{await launchExamDomain(attemptId)}catch(e){console.error('[SLC][EXAM_LAUNCH_FAILED]',{attemptId,status:e?.status,message:e?.message,data:e?.data});slcNotice('Không thể mở Trung tâm Dự thi',e?.message||'Vui lòng thử lại.')}}

