async function account(){const [sessions,prof]=await Promise.all([api('/api/account/sessions').catch(()=>({sessions:[]})),api('/api/account/profile').catch(()=>({profile:state.user,preferences:{}}))]);const u=normalizeUser(prof?.profile)||normalizeUser(state.user)||normalizeUser({});state.user=u;app.innerHTML=shell(`<section class="profile-head">${avatarMarkup(state.user,'xl')}<div><div class="eyebrow">HỒ SƠ & TÀI KHOẢN</div><h1>${esc(userDisplayName(u))}</h1><p>${esc(u?.sfn_id||'SFN')} · ${esc(roleLabel(u?.role))}</p></div></section><div class="settings-layout"><aside class="settings-nav"><button class="active">Hồ sơ cá nhân</button><button>Bảo mật</button><button>Phiên & thiết bị</button><button>Tùy chọn</button></aside><section class="settings-content"><div class="settings-card"><h2>Ảnh đại diện</h2><div class="avatar-editor">${avatarMarkup(state.user,'xl')}<form id="avatarForm"><input type="file" name="avatar" accept="image/jpeg,image/png,image/webp" required><div class="toolbar"><button class="btn primary">Đổi ảnh</button><button class="btn" type="button" id="removeAvatar">Xóa ảnh</button></div></form></div><p class="muted">Nếu không có ảnh, hệ thống dùng chữ cái từ tên gọi của bạn.</p></div><form class="settings-card" id="profileForm"><h2>Thông tin cá nhân</h2><div class="two"><div class="field"><label>Họ và tên</label><input name="full_name" value="${esc(userDisplayName(u))}" required></div><div class="field"><label>Số điện thoại</label><input name="phone" value="${esc(u?.phone||'')}"></div></div><div class="field"><label>Email</label><input value="${esc(u?.email||'')}" disabled></div><button class="btn primary">Lưu thay đổi</button></form><form class="settings-card" id="passwordForm"><h2>Bảo mật</h2><div class="two"><div class="field"><label>Mật khẩu hiện tại</label><input type="password" name="current_password" required></div><div class="field"><label>Mật khẩu mới</label><input type="password" name="new_password" minlength="10" required></div><div class="field"><label>Nhập lại mật khẩu mới</label><input type="password" name="confirm_password" minlength="10" required></div></div><button class="btn">Đổi mật khẩu</button></form><div class="settings-card"><h2>Phiên & thiết bị</h2>${arr(sessions.sessions).map(x=>`<div class="session-row"><div><b>${x.current?'Thiết bị hiện tại':'Phiên đăng nhập'}</b><small>${esc(x.user_agent||'Thiết bị không xác định')} · ${esc(x.created_at)}</small></div>${!x.current?`<button class="btn" data-kill-session="${x.id}">Đăng xuất</button>`:''}</div>`).join('')||'<p class="muted">Không có phiên khác.</p>'}</div></section></div>`);bindNav();$('#avatarForm').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input[type=file]'),blob=await cropAvatarFile(input.files?.[0]);if(!blob)return;const fd=new FormData();fd.append('avatar',blob,'avatar.webp');await api('/api/account/avatar',{method:'POST',body:fd});await loadMe();account()};$('#removeAvatar').onclick=async()=>{await api('/api/account/avatar',{method:'DELETE'});await loadMe();account()};$('#profileForm').onsubmit=async e=>{e.preventDefault();await api('/api/account/profile',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadMe();account()};$('#passwordForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.new_password!==b.confirm_password)return slcNotice('Thông báo','Mật khẩu nhập lại chưa khớp.');await api('/api/account/password',{method:'POST',body:JSON.stringify(b)});slcNotice('Thông báo','Đã đổi mật khẩu và đăng xuất các phiên khác.');e.target.reset()};document.querySelectorAll('[data-kill-session]').forEach(b=>b.onclick=async()=>{await api(`/api/account/sessions/${b.dataset.killSession}`,{method:'DELETE'});account()})}


async function operationsCenter(){
  if(!['super_admin','school_admin'].includes(state.user?.role))return admin();
  const [o,roles,assignments,autos,analytics,certs,fields,programs,classList]=await Promise.all([api('/api/admin/v39/overview').catch(()=>({})),api('/api/admin/v39/roles').catch(()=>({roles:[]})),api('/api/admin/v39/role-assignments').catch(()=>({assignments:[]})),api('/api/admin/v39/automations').catch(()=>({rules:[]})),api('/api/admin/v39/analytics').catch(()=>({metrics:[]})),api('/api/admin/certificates').catch(()=>({certificates:[]})),api('/api/admin/education-fields').catch(()=>({fields:[]})),api('/api/admin/education-programs').catch(()=>({programs:[]})),api('/api/classes').catch(()=>({classes:[]}))]);
  app.innerHTML=shell(`<section class="hero"><div class="eyebrow">DIGITAL EDUCATION OPERATIONS</div><h1>Chương trình · Lớp · Vận hành hàng loạt · Quyền · Dữ liệu</h1><p>SLCS là control plane quản lý và điều hành hoạt động giáo dục; lớp học, nhân sự, lịch, đánh giá và dữ liệu được thao tác theo context thay vì buộc quản trị viên xử lý từng người.</p><div class="toolbar"><span class="pill">${Number(o.members||0)} thành viên</span><span class="pill">${Number(o.classes||0)} lớp</span><span class="pill">${Number(o.assessments||0)} đánh giá</span><span class="pill">${arr(programs?.programs).length} chương trình</span></div></section><section class="story-grid"><article class="card span2"><div class="toolbar" style="justify-content:space-between"><div><h2>FIELD → PROGRAM → COHORT → CLASS</h2><p class="muted">Mô hình chương trình không khóa cứng theo Toán/Văn/Anh.</p></div><button class="btn" id="eduFieldAdd">+ Lĩnh vực</button></div><form id="eduProgram"><div class="two"><div class="field"><label>Mã chương trình</label><input name="code" required placeholder="ENG-FOUNDATION"></div><div class="field"><label>Tên chương trình</label><input name="name" required></div><div class="field"><label>Lĩnh vực</label><select name="field_id"><option value="">Chưa phân loại</option>${arr(fields?.fields).map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="field"><label>Quy mô mục tiêu</label><input type="number" name="scale_target" min="0"></div></div><div class="field"><label>Đối tượng</label><input name="audience" placeholder="Ví dụ: học viên mất gốc / lớp 10–12"></div><button class="btn primary">Tạo chương trình</button></form><div class="list">${arr(programs?.programs).map(p=>`<div class="item"><b>${esc(p.code)} · ${esc(p.name)}</b><div class="muted">${esc(p.field_name||'Chưa phân lĩnh vực')} · ${Number(p.cohort_count||0)} đợt · ${Number(p.class_count||0)} lớp · ${esc(p.status||'draft')}</div><button class="btn" data-cohort-add="${p.id}">+ Đợt triển khai</button></div>`).join('')||'<div class="muted">Chưa có chương trình.</div>'}</div></article><article class="card span2"><h2>Mass Operations</h2><p class="muted">Thao tác theo lô trên danh sách ID; backend giới hạn 1.000 người và 200 lớp/lần để tránh request vô hạn.</p><form id="bulkOps"><div class="two"><div class="field"><label>Thao tác</label><select name="action"><option value="enroll">Xếp học viên vào lớp</option><option value="assign_role">Phân GV/TG theo lớp</option><option value="class_status">Đổi trạng thái lớp</option><option value="announce">Thông báo hàng loạt</option></select></div><div class="field"><label>Vai trò</label><select name="role"><option value="student">Học viên</option><option value="assistant">Trợ giảng</option><option value="teacher">Giáo viên</option></select></div></div><div class="field"><label>User ID — phân cách dấu phẩy</label><textarea name="user_ids" placeholder="uuid-1, uuid-2, ..."></textarea></div><div class="field"><label>Class ID — phân cách dấu phẩy</label><textarea name="class_ids" placeholder="${arr(classList?.classes).slice(0,2).map(c=>c.id).join(', ')}"></textarea></div><div class="field"><label>Nội dung thông báo (chỉ dùng khi chọn Thông báo)</label><textarea name="body"></textarea></div><div class="two"><div class="field"><label>Trạng thái lớp</label><select name="status"><option value="active">Đang hoạt động</option><option value="archived">Lưu trữ</option></select></div><div class="field"><label>&nbsp;</label><button class="btn primary" style="width:100%">Thực hiện hàng loạt</button></div></div></form></article></section><section class="story-grid"><article class="card"><h2>Vai trò & quyền</h2><form id="v39Role"><div class="field"><label>Tên vai trò</label><input name="name" required placeholder="Ví dụ: Giám thị"></div><div class="field"><label>Quyền chức năng (phân cách bằng dấu phẩy)</label><input name="permissions" placeholder="assessment.monitor, assessment.reopen"></div><button class="btn primary">Tạo vai trò</button></form><div class="list">${arr(roles?.roles).map(r=>`<div class="item"><b>${esc(r.name)}</b><div class="muted">${esc(r.permissions||'Chưa cấp quyền')}</div></div>`).join('')||'<div class="muted">Chưa có vai trò tùy chỉnh.</div>'}</div><hr><h3>Gán vai trò</h3><form id="v39AssignRole"><div class="field"><input name="login" placeholder="SFN ID hoặc email" required></div><div class="field"><select name="role_id" required><option value="">Chọn vai trò</option>${arr(roles?.roles).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div><button class="btn">Gán quyền</button></form><div class="list">${arr(assignments?.assignments).map(a=>`<div class="item"><b>${esc(a.full_name)} · ${esc(a.role_name)}</b><div class="muted">${esc(a.sfn_id)} · ${esc(a.permissions||'')}</div><button class="btn danger" data-unassign-role="${a.user_id}" data-role-id="${a.role_id}">Gỡ</button></div>`).join('')||'<div class="muted">Chưa có phân quyền tùy chỉnh.</div>'}</div></article><article class="card"><h2>Tự động hóa</h2><button class="btn" id="v39RunDue" type="button">Chạy kiểm tra đến hạn / ticket cũ</button><form id="v39Automation"><div class="field"><label>Tên quy tắc</label><input name="name" required></div><div class="two"><div class="field"><label>Khi</label><select name="trigger_key"><option>account.created</option><option>assessment.published</option><option>assessment.submitted</option><option>assignment.due</option><option>ticket.stale</option></select></div><div class="field"><label>Thì</label><select name="action_key"><option>notification.create</option><option>email.send</option><option>audit.record</option></select></div></div><button class="btn primary">Tạo quy tắc</button></form><div class="list">${arr(autos?.rules).map(r=>`<div class="item"><b>${esc(r.name)}</b><div class="muted">${esc(r.trigger_key)} → ${esc(r.action_key)} · ${r.enabled?'Đang bật':'Đang tắt'}</div></div>`).join('')||'<div class="muted">Chưa có quy tắc.</div>'}</div></article><article class="card span2"><h2>Phân tích 30 ngày</h2><div class="story-grid">${arr(analytics?.metrics).map(m=>`<div class="item"><b>${esc(m.event_key)}</b><div>${Number(m.count||0)} sự kiện</div><small>${m.average_value==null?'':`Giá trị TB ${esc(m.average_value)}`}</small></div>`).join('')||'<div class="muted">Chưa có dữ liệu phân tích. Hệ thống sẽ tích lũy sau khi bắt đầu ghi nhận hoạt động.</div>'}</div></article><article class="card span2"><h2>Chứng nhận & xác minh</h2><form id="issueCertificate"><div class="two"><div class="field"><label>SFN ID hoặc email người nhận</label><input name="login" required></div><div class="field"><label>Tên ghi nhận</label><input name="title" required></div></div><div class="field"><label>ID lớp (không bắt buộc)</label><input name="class_id"></div><button class="btn primary">Cấp ghi nhận</button></form><div class="list">${arr(certs?.certificates).map(c=>`<div class="item"><b>${esc(c.certificate_code)} · ${esc(c.title)}</b><div class="muted">${esc(c.full_name)} · ${esc(c.sfn_id)} · ${esc(c.status)}</div><div class="toolbar"><button class="btn" data-go="verify-certificate/${encodeURIComponent(c.certificate_code)}">Xác minh</button>${c.status==='issued'?`<button class="btn danger" data-revoke-certificate="${c.id}">Thu hồi</button>`:''}</div></div>`).join('')||'<div class="muted">Chưa có ghi nhận trong tổ chức.</div>'}</div></article></section>`);bindNav();$('#eduFieldAdd')?.addEventListener('click',async()=>{const f=await slcForm('Tạo lĩnh vực','Lĩnh vực là lớp phân loại cao nhất của chương trình.',[{name:'code',label:'Mã lĩnh vực',required:true},{name:'name',label:'Tên lĩnh vực',required:true},{name:'description',label:'Mô tả',type:'textarea'}],'Tạo lĩnh vực');if(!f?.code)return;await api('/api/admin/education-fields',{method:'POST',body:JSON.stringify(f)});operationsCenter()});$('#eduProgram')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.scale_target=d.scale_target===''?null:Number(d.scale_target);await api('/api/admin/education-programs',{method:'POST',body:JSON.stringify(d)});operationsCenter()});document.querySelectorAll('[data-cohort-add]').forEach(b=>b.onclick=async()=>{const f=await slcForm('Tạo đợt triển khai','Mỗi chương trình có thể có nhiều cohort/đợt triển khai.',[{name:'code',label:'Mã đợt',required:true},{name:'name',label:'Tên đợt',required:true},{name:'starts_at',label:'Bắt đầu',type:'datetime-local'},{name:'ends_at',label:'Kết thúc',type:'datetime-local'},{name:'capacity',label:'Quy mô',type:'number',min:0}],'Tạo đợt');if(!f?.code)return;await api(`/api/admin/education-programs/${b.dataset.cohortAdd}/cohorts`,{method:'POST',body:JSON.stringify(f)});operationsCenter()});$('#bulkOps')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.user_ids=String(d.user_ids||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);d.class_ids=String(d.class_ids||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);const r=await api('/api/admin/bulk-operations',{method:'POST',body:JSON.stringify(d)});slcNotice('Mass Operations',`Đã xử lý ${Number(r.changed||0)} mục.`);operationsCenter()});$('#v39Role').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.permissions=String(d.permissions||'').split(',').map(x=>x.trim()).filter(Boolean);await api('/api/admin/v39/roles',{method:'POST',body:JSON.stringify(d)});operationsCenter()};$('#v39AssignRole')?.addEventListener('submit',async e=>{e.preventDefault();await api('/api/admin/v39/role-assignments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});operationsCenter()});document.querySelectorAll('[data-unassign-role]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/v39/role-assignments/${b.dataset.unassignRole}/${b.dataset.roleId}`,{method:'DELETE'});operationsCenter()});$('#v39RunDue')?.addEventListener('click',async()=>{await api('/api/admin/v39/automations/run-due',{method:'POST',body:'{}'});slcNotice('Đã chạy Automation','Đã kiểm tra bài tập đến hạn và ticket quá 48 giờ.');operationsCenter()});$('#v39Automation').onsubmit=async e=>{e.preventDefault();await api('/api/admin/v39/automations',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});operationsCenter()};$('#issueCertificate')?.addEventListener('submit',async e=>{e.preventDefault();const r=await api('/api/admin/certificates',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});slcNotice('Đã cấp ghi nhận',`Mã xác minh: ${r.certificate_code}`);operationsCenter()});document.querySelectorAll('[data-revoke-certificate]').forEach(b=>b.onclick=async()=>{const reason=await slcTextInput('Thu hồi ghi nhận','Nhập lý do thu hồi. Nội dung này được lưu vào lịch sử.','Lý do thu hồi');if(!reason)return;await api(`/api/admin/certificates/${b.dataset.revokeCertificate}/revoke`,{method:'POST',body:JSON.stringify({reason})});operationsCenter()});
}

async function organizationAdmin(){
  if(state.user?.role!=='super_admin'){location.hash='admin';return}
  let j,loadError='';try{j=await api('/api/admin/organizations')}catch(err){console.error('[SLC][ORGANIZATIONS_LOAD_FAILED]',err);loadError=err?.message||'Không tải được dữ liệu tổ chức.';j={organizations:[]}}
  app.innerHTML=shell(`<section class="page-head"><div><div class="eyebrow">PLATFORM ADMINISTRATION</div><h1>Tổ chức & Gói quyền</h1><p>Quản lý workspace, trạng thái, entitlement và quota trên cùng nền tảng.</p></div><button class="btn" data-go="admin">← Control Center</button></section>
  ${loadError?`<div class="notice bad" style="margin-bottom:16px"><b>Không tải được Tổ chức & Gói quyền.</b><br>${esc(loadError)} <button class="btn" id="retryOrganizations" style="margin-left:8px">Thử lại</button></div>`:''}<section class="admin-org-grid"><article class="card"><h2>Tạo tổ chức</h2><form id="createOrg"><div class="field"><label>Tên tổ chức</label><input name="name" required minlength="2"></div><div class="two"><div class="field"><label>Slug</label><input name="slug" placeholder="clb-abc"></div><div class="field"><label>Gói</label><select name="plan"><option value="community">Community Sponsored</option><option value="standard">Standard</option><option value="pro">Pro</option></select></div></div><button class="btn primary">Tạo workspace</button></form></article>
  <article class="card span2"><h2>Danh sách tổ chức</h2><div class="org-admin-list">${arr(j?.organizations).map(o=>`<button class="org-admin-row" data-org="${esc(o.id)}"><span><b>${esc(o.name)}</b><small>${esc(o.slug)} · ${esc(o.subscription_plan||o.plan||'community')}</small></span><span>${Number(o.member_count||0)} thành viên · ${Number(o.class_count||0)} lớp</span><em>${esc(o.status)}</em></button>`).join('')||'<div class="empty-state">Chưa có tổ chức.</div>'}</div></article></section><div id="orgEditor"></div>`);
  bindNav();
  $('#retryOrganizations')?.addEventListener('click',organizationAdmin);
  $('#createOrg').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button');const old=btn.textContent;btn.disabled=true;btn.textContent='Đang tạo…';try{const b=Object.fromEntries(new FormData(form));await api('/api/admin/organizations',{method:'POST',body:JSON.stringify(b)});await organizationAdmin()}catch(err){console.error('[SLC][ORGANIZATION_CREATE_FAILED]',err);slcNotice('Thông báo',err?.message||'Không thể tạo tổ chức.')}finally{if(document.contains(btn)){btn.disabled=false;btn.textContent=old}}};
  document.querySelectorAll('[data-org]').forEach(b=>b.onclick=()=>openOrganizationEditor(b.dataset.org,arr(j?.organizations).find(x=>x?.id===b.dataset.org)));
}
async function openOrganizationEditor(id,org){
  const [e,u]=await Promise.all([api(`/api/admin/organizations/${id}/entitlements`),api(`/api/admin/organizations/${id}/usage`)]); const map=Object.fromEntries(arr(e?.entitlements).map(x=>[x?.capability,x]));
  const caps=[['guest.access','Guest'],['teaching.core','Teaching'],['website.studio','Website Studio'],['classes','Classes'],['members','Members'],['storage.bytes','Storage bytes']];
  $('#orgEditor').innerHTML=`<dialog class="org-editor" open><form method="dialog"><button class="dialog-x" value="cancel">×</button><div class="eyebrow">ORGANIZATION STUDIO</div><h2>${esc(org?.name||id)}</h2><p class="muted">Usage hiện tại: ${Number(u.members||0)} thành viên · ${Number(u.classes||0)} lớp</p><div class="entitlement-grid">${caps.map(([k,n])=>{const x=map[k]||{};return `<label class="entitlement-item"><span><b>${n}</b><small>${k}</small></span><input type="checkbox" data-cap-enabled="${k}" ${x.enabled?'checked':''}>${['classes','members','storage.bytes'].includes(k)?`<input type="number" data-cap-quota="${k}" value="${x.quota_value??''}" placeholder="Quota">`:''}</label>`}).join('')}</div><div class="toolbar"><select id="orgStatus"><option value="active" ${org?.status==='active'?'selected':''}>Active</option><option value="suspended" ${org?.status==='suspended'?'selected':''}>Suspended</option><option value="trial" ${org?.status==='trial'?'selected':''}>Trial</option><option value="expired" ${org?.status==='expired'?'selected':''}>Expired</option></select><button type="button" class="btn primary" id="saveOrgEnt">Lưu quyền & quota</button></div></form></dialog>`;
  $('#saveOrgEnt').onclick=async()=>{const entitlements=caps.map(([cap])=>({capability:cap,enabled:!!document.querySelector(`[data-cap-enabled="${cap}"]`)?.checked,quota_value:document.querySelector(`[data-cap-quota="${cap}"]`)?.value||null,source:'override'}));await api(`/api/admin/organizations/${id}/entitlements`,{method:'PUT',body:JSON.stringify({entitlements})});await api(`/api/admin/organizations/${id}`,{method:'PATCH',body:JSON.stringify({status:$('#orgStatus').value})});$('#orgEditor').innerHTML='';organizationAdmin()};
}
const LEGAL_CONTENT={
privacy:`<h2>1. Phạm vi và nguyên tắc</h2><p>Chính sách quyền riêng tư này giải thích cách Trung tâm Học tập số Sky First Network tiếp nhận, sử dụng và bảo vệ thông tin trong quá trình cung cấp tài khoản, lớp học, hoạt động trực tuyến, hỗ trợ và các tính năng liên quan. Chúng tôi hướng tới việc chỉ xử lý những dữ liệu cần thiết cho mục đích vận hành, học tập, xác minh, an toàn và hỗ trợ người dùng. Việc một thông tin được cung cấp cho hệ thống không đồng nghĩa thông tin đó sẽ được công khai. Quyền xem dữ liệu phụ thuộc vào vai trò, lớp học, nhiệm vụ và phạm vi được cấp.</p><h2>2. Thông tin có thể được xử lý</h2><p>Thông tin có thể bao gồm họ tên, ngày sinh, email, số điện thoại, mã tài khoản Sky First Network, thông tin học tập, đơn vị tham gia, vai trò, ảnh xác minh và các dữ liệu mà người dùng chủ động gửi trong quá trình yêu cầu tài khoản. Khi sử dụng lớp học, hệ thống có thể xử lý nội dung bài nộp, tài liệu, tin nhắn, phản hồi hoạt động, trạng thái tham gia, lịch sử lớp và dữ liệu cần thiết để duy trì phiên đăng nhập.</p><h2>4. Người học chưa thành niên</h2><p>Môi trường học tập có thể phục vụ người chưa thành niên, vì vậy việc bảo vệ người học được ưu tiên trong thiết kế quyền truy cập và kiểm soát nội dung. Hệ thống hạn chế nội dung tình dục rõ ràng, khai thác hoặc dụ dỗ tình dục trẻ vị thành niên và những yêu cầu không phù hợp với môi trường giáo dục. Việc thảo luận về sinh học, sức khỏe sinh sản, giáo dục giới tính, phòng chống xâm hại hoặc nội dung học thuật hợp lệ không bị đánh đồng với nội dung khiêu dâm và được xem xét theo ngữ cảnh.</p><h2>5. Chia sẻ và quyền truy cập</h2><p>Dữ liệu không được mặc định chia sẻ cho mọi người dùng. Giáo viên, trợ giảng, quản trị trường và quản trị hệ thống có phạm vi khác nhau. Thông tin kỹ thuật vận hành chuyên sâu chỉ dành cho người quản trị hệ thống được ủy quyền. Dữ liệu có thể được xử lý bởi nhà cung cấp hạ tầng hoặc dịch vụ cần thiết để nền tảng hoạt động, nhưng chỉ trong phạm vi phục vụ chức năng tương ứng. Chúng tôi không trình bày Sky First Network như một cơ quan nhà nước, tổ chức chứng nhận chính thức hoặc pháp nhân có thẩm quyền mà không có căn cứ phù hợp.</p><h2>6. Lưu giữ, an toàn và lựa chọn của người dùng</h2><p>Dữ liệu được lưu trong thời gian hợp lý cho mục đích tài khoản, lớp học, hỗ trợ, an toàn và nghĩa vụ vận hành. Một số nhật ký có thể được giữ để điều tra sự cố hoặc chống lạm dụng. Người dùng cần bảo vệ mật khẩu, không chia sẻ liên kết kích hoạt và đăng xuất khỏi thiết bị không còn sử dụng. Khi cần hỏi về dữ liệu, chỉnh sửa thông tin hoặc báo cáo vấn đề quyền riêng tư, người dùng có thể sử dụng Trung tâm hỗ trợ hoặc Zalo/Hotline 0924 910 210. Chính sách có thể được cập nhật khi tính năng, quy trình hoặc yêu cầu vận hành thay đổi; phiên bản đang hiển thị trên nền tảng là phiên bản áp dụng tại thời điểm truy cập.</p>`,
security:`<h2>1. Mục tiêu bảo mật</h2><p>Bảo mật tại Trung tâm Học tập số Sky First Network được xây dựng quanh ba mục tiêu: bảo vệ tài khoản, giới hạn quyền truy cập đúng vai trò và duy trì trải nghiệm học tập ổn định. Người dùng thông thường không cần nhìn thấy cấu trúc kỹ thuật phía sau nền tảng. Khi có sự cố, hệ thống ưu tiên thông báo dễ hiểu và hướng dẫn hành động phù hợp thay vì hiển thị thông tin nội bộ có thể gây nhầm lẫn hoặc làm tăng rủi ro.</p><h2>2. Tài khoản và phiên đăng nhập</h2><p>Mỗi người dùng cần giữ bí mật mật khẩu, liên kết kích hoạt và các thông tin xác thực. Không sử dụng chung tài khoản nếu chưa được cho phép. Nếu nghi ngờ tài khoản bị truy cập trái phép, hãy đổi mật khẩu, kết thúc các phiên không nhận ra và liên hệ hỗ trợ. Hệ thống có thể giới hạn phiên, buộc đăng xuất hoặc tạm khóa tài khoản khi phát hiện dấu hiệu cần bảo vệ người dùng hoặc nền tảng.</p><h2>3. Phân quyền</h2><p>Học sinh, giáo viên, trợ giảng, quản trị tài khoản, quản trị trường và quản trị hệ thống có phạm vi khác nhau. Một vai trò không được tự động nhìn thấy dữ liệu của vai trò cao hơn. Quản trị trường có thể quản lý hoạt động phù hợp nhưng không mặc định được xem thông tin hạ tầng chuyên sâu. Chỉ quản trị hệ thống được ủy quyền mới truy cập các khu vực chẩn đoán và vận hành kỹ thuật. Việc kiểm tra quyền được thực hiện ở máy chủ; ẩn nút trên giao diện không được coi là biện pháp bảo mật duy nhất.</p><h2>4. Lớp học và kiểm tra</h2><p>Trong lớp học số, quyền quản lý và thao tác được kiểm tra theo vai trò. Khi một phiên kiểm tra đang hoạt động, hệ thống có thể khóa các khu vực không liên quan ngay tại máy chủ để duy trì tính tập trung và công bằng.</p><h2>5. Tệp và nội dung</h2><p>Người dùng chỉ nên tải lên tài liệu có quyền sử dụng và phù hợp với hoạt động. Không tải phần mềm độc hại, nội dung nhằm phá hệ thống, dữ liệu cá nhân của người khác khi không có lý do hợp lệ hoặc tài liệu vi phạm quyền sở hữu trí tuệ. Những tệp riêng tư không được mặc định công khai. Quyền tải xuống hoặc xem có thể phụ thuộc lớp, tài khoản và trạng thái hoạt động.</p><h2>6. Báo cáo sự cố</h2><p>Nếu phát hiện lỗ hổng, tài khoản bị chiếm quyền, hành vi lạm dụng hoặc dữ liệu hiển thị sai phạm vi, hãy báo qua Trung tâm hỗ trợ hoặc Zalo/Hotline 0924 910 210. Không khai thác lỗ hổng để truy cập thêm dữ liệu, không công bố bí mật, khóa truy cập hoặc thông tin cá nhân. Chúng tôi có thể yêu cầu thông tin mô tả, thời điểm và bước tái hiện ở mức cần thiết để điều tra. Bảo mật là quá trình liên tục; các biện pháp có thể được điều chỉnh khi nền tảng phát triển và khi xuất hiện rủi ro mới.</p>`,
terms:`<h2>1. Chấp nhận điều khoản</h2><p>Khi truy cập hoặc sử dụng Trung tâm Học tập số Sky First Network, người dùng đồng ý sử dụng nền tảng cho mục đích học tập, giảng dạy, quản trị hoặc hoạt động được cho phép. Nếu không đồng ý với điều khoản đang áp dụng, người dùng nên ngừng sử dụng và liên hệ hỗ trợ để được giải thích. Quyền truy cập không đồng nghĩa quyền sở hữu hệ thống hoặc quyền sử dụng mọi dữ liệu có thể nhìn thấy.</p><h2>2. Tài khoản và trách nhiệm</h2><p>Người dùng phải cung cấp thông tin hợp lý trong quá trình đăng ký hoặc xác minh, bảo vệ thông tin đăng nhập và không giả mạo người khác. Tài khoản có thể được cấp theo vai trò và có thể thay đổi khi nhiệm vụ thay đổi. Việc cho mượn tài khoản, cố vượt quyền, truy cập dữ liệu không thuộc phạm vi hoặc can thiệp vào cơ chế bảo vệ có thể dẫn đến hạn chế hoặc đình chỉ truy cập.</p><h2>3. Quy tắc trong lớp học</h2><p>Người dùng cần tôn trọng người học, giáo viên và thành viên khác; không quấy rối, đe dọa, phát tán thông tin cá nhân, phá buổi học hoặc gửi nội dung gây hại.</p><h2>4. Kiểm tra và trung thực học tập</h2><p>Khi tham gia bài kiểm tra, người học phải tuân thủ hướng dẫn của người phụ trách. Trong phiên kiểm tra, một số chức năng như các khu vực không liên quan có thể bị khóa hoàn toàn. Cố tình can thiệp vào cơ chế kỹ thuật, sử dụng tài khoản khác, khai thác lỗi hoặc tìm cách vượt chế độ kiểm tra có thể được xem là hành vi vi phạm. Tuy nhiên, một tín hiệu kỹ thuật đơn lẻ không nên tự động được coi là bằng chứng gian lận; người phụ trách cần xem xét bối cảnh trước khi kết luận.</p><h2>5. Nội dung và an toàn</h2><p>Không sử dụng nền tảng để tạo, chia sẻ hoặc yêu cầu nội dung tình dục rõ ràng không phù hợp môi trường giáo dục, nội dung khai thác tình dục trẻ vị thành niên, dụ dỗ tình dục, bạo lực nhằm đe dọa người khác, mã độc hoặc hướng dẫn phá hoại hệ thống. Nội dung giáo dục giới tính, sinh học, sức khỏe sinh sản và phòng chống xâm hại có mục đích học tập hợp lệ được xem xét theo ngữ cảnh. Người dùng chịu trách nhiệm về tài liệu mình tải lên và phải tôn trọng bản quyền, quyền riêng tư và quyền của người khác.</p><h2>6. Giới hạn dịch vụ</h2><p>Nền tảng có thể thay đổi tính năng, giới hạn sử dụng hoặc tạm ngừng một phần dịch vụ để bảo trì hay bảo vệ hệ thống. Khi có vi phạm, chúng tôi có thể cảnh báo, hạn chế chức năng, kết thúc phiên, khóa tài khoản hoặc thực hiện biện pháp phù hợp với mức độ và bối cảnh.</p>`,
support:`<h2>1. Trung tâm hỗ trợ dành cho ai?</h2><p>Trung tâm hỗ trợ là nơi người học, giáo viên, trợ giảng và các vai trò quản trị tìm hướng dẫn khi gặp vấn đề với tài khoản, lớp học và bài kiểm tra. Mục tiêu là giúp người dùng tự giải quyết những tình huống phổ biến trước, đồng thời cung cấp đường liên hệ rõ ràng khi cần người phụ trách hỗ trợ trực tiếp.</p><h2>2. Tài khoản và đăng nhập</h2><p>Nếu chưa có tài khoản, hãy sử dụng chức năng Yêu cầu cấp tài khoản và lưu mã tra cứu sau khi gửi. Nếu đã được duyệt nhưng chưa đăng nhập được, kiểm tra SFN ID hoặc email, mật khẩu và trạng thái kích hoạt. Không gửi mật khẩu, khóa truy cập, mã bí mật hoặc liên kết kích hoạt riêng tư cho người khác. Nếu nghi ngờ tài khoản bị truy cập trái phép, đổi mật khẩu và kết thúc những phiên không nhận ra trong trang Tài khoản.</p><h2>3. Lớp học</h2><p>Nếu không thấy lớp, hãy kiểm tra tài khoản đang đăng nhập và xác nhận bạn đã được thêm vào lớp hoặc có mã tham gia hợp lệ.</p><h2>4. Bài kiểm tra</h2><p>Khi bắt đầu bài kiểm tra, hãy đọc kỹ thời lượng và hướng dẫn. Nếu phiên đang hoạt động, hệ thống có thể đưa bạn trở lại bài làm và cất các khu vực khác. Đây là hành vi dự kiến của Chế độ kiểm tra. Các khu vực không liên quan không khả dụng cho người làm bài trong thời gian này. Nếu mất kết nối, hãy mở lại nền tảng bằng cùng tài khoản; hệ thống sẽ cố khôi phục phiên còn hiệu lực. Nếu gặp sự cố ảnh hưởng việc nộp bài, hãy ghi lại thời điểm và báo giáo viên hoặc hỗ trợ.</p><h2>6. Liên hệ</h2><p>Nếu hướng dẫn trên chưa giải quyết được vấn đề, hãy mô tả ngắn gọn việc bạn đang làm, trang đang mở, thời điểm xảy ra và thông báo mà bạn nhìn thấy. Không cần gửi thông tin kỹ thuật chuyên sâu nếu bạn không biết. Bạn có thể liên hệ Zalo/Hotline <b>0924 910 210</b>. Các kênh chính thức khác được liệt kê ở cuối trang, bao gồm Trang điện tử Sky First Network, Cổng thông tin, không gian Tình nguyện viên và các kênh mạng xã hội. Khi báo lỗi liên quan tài khoản, nên cung cấp họ tên và SFN ID nhưng không cung cấp mật khẩu.</p>`
};

async function policy(type){const titles={privacy:'Chính sách quyền riêng tư',security:'Bảo mật',terms:'Điều khoản sử dụng',support:'Trung tâm hỗ trợ'};let body=LEGAL_CONTENT[type]||LEGAL_CONTENT.support;if(type!=='support'){try{const p=(await api(`/api/public/policies/${type}`,{cacheTtl:60000})).policy;if(p?.body_html&&String(p.body_html).replace(/<[^>]+>/g,' ').trim().split(/\s+/).length>=500)body=p.body_html}catch{}}app.innerHTML=shell(`<section class="hero policy-hero"><div class="eyebrow">TRUNG TÂM HỌC TẬP SỐ SKY FIRST</div><h1>${titles[type]||'Thông tin'}</h1><p>Thông tin minh bạch dành cho người sử dụng và cộng đồng.</p></section><article class="policy-document">${safeRichHtml(body)}<div class="policy-contact"><b>Cần hỗ trợ thêm?</b><p>Zalo/Hotline: <a href="tel:0924910210">0924 910 210</a> · ${esc(state.site.support_email||'support@skyfirst.io.vn')}</p></div></article>`);bindNav()}

async function activate(token){app.innerHTML=shell(`<div class="auth-wrap"><form class="auth-card" id="actForm"><div class="eyebrow">Kích hoạt SFN Account</div><h1>Tạo mật khẩu</h1><div class="field"><label>Mật khẩu mới</label><input name="password" type="password" minlength="10" required></div><div id="msg" role="status" aria-live="polite"></div><button class="btn primary">Kích hoạt</button></form></div>`);bindNav();$('#actForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/activate',{method:'POST',body:JSON.stringify({token,password:new FormData(e.target).get('password')})});$('#msg').innerHTML='<div class="notice good">Kích hoạt thành công. Bạn có thể đăng nhập.</div>'}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}}}


async function loadSystemStatus(){try{const j=await api('/api/setup/status');state.system={initialized:!!j.initialized,schema_ready:j.schema_ready!==false}}catch{state.system={initialized:false,schema_ready:false}}}
async function loadPublicConfig(){try{const j=await api('/api/public/site-config',{cacheTtl:60000});state.site=obj(j?.settings);state.siteAnnouncements=arr(j?.announcements);}catch{state.site={};state.siteAnnouncements=[]}}
async function loadMe({throwOnServerError=false}={}){try{const j=await api('/api/auth/me',{cacheTtl:0});state.user=normalizeUser(j?.user);state.activeExam=j?.active_exam&&typeof j.active_exam==='object'?j.active_exam:null;return state.user}catch(error){state.user=null;state.activeExam=null;if(throwOnServerError&&Number(error?.status||0)>=500)throw error;return null}}
async function loadOrganizations(){if(!state.user){state.organizations=[];state.organizationId='sky-first';return}try{const j=await api('/api/organizations/mine',{cacheTtl:10000});state.organizations=normalizeOrganizations(j?.organizations);const saved=storageGet('slc_org');state.organizationId=state.organizations.some(o=>o.id===saved)?saved:(state.organizations[0]?.id||'sky-first');const current=state.organizations.find(o=>o.id===state.organizationId);if(state.user&&current?.permissions)state.user.permissions=arr(current.permissions)}catch{state.organizations=[];state.organizationId='sky-first'}}
async function renderRoute(){syncUiContext();const h=location.hash.replace(/^#/,'')||'home';if(state.site?.maintenance_mode==='1'&&!state.user&&!['login','privacy','security','terms','support'].includes(h)){app.innerHTML=shell(`<section class="hero"><div class="eyebrow">THÔNG BÁO HỆ THỐNG</div><h1>Trung tâm đang được bảo trì.</h1><p>${esc(state.site.maintenance_message||'Vui lòng quay lại sau.')}</p><button class="btn" data-go="login">Đăng nhập quản trị</button></section>`);bindNav();return;}if(!state.system.initialized && !['privacy','security','terms'].includes(h) && !h.startsWith('activate/')) return setupFirstAdmin();if(!state.user && !['home','login','request','lookup','privacy','security','terms','support'].includes(h) && !h.startsWith('activate/') && !h.startsWith('assessment-invite/') && !h.startsWith('guest-exam/') && !h.startsWith('verify-certificate/')) await loadMe();if(state.user&&state.activeExam&&!h.startsWith('exam/')&&!['login'].includes(h)){await resumeExam(state.activeExam.attempt_id);return;}if(h==='home')return state.user?home():landing();if(h==='login')return login();if(h==='request')return requestAccount();if(h==='lookup')return lookupAccount();if(h==='classes')return state.user?classes():login();if(h==='exam-center')return state.user?examCenter():login();if(h==='calendar')return state.user?calendarView():login();if(h==='resources')return state.user?resourcesView():login();if(h==='search')return state.user?globalSearch():login();if(h==='certificates')return state.user?certificatesView():login();if(h==='command-center')return state.user?commandCenter():login();if(h==='notifications')return state.user?notificationsView():login();if(h==='support')return state.user?support():policy('support');if(h==='account')return state.user?account():login();if(h==='admin')return state.user?admin():login();if(h==='admin-assessments')return state.user?adminAssessmentCenter():login();if(h==='admin-organizations')return state.user?organizationAdmin():login();if(h==='admin-operations')return state.user?operationsCenter():login();if(h==='privacy'||h==='security'||h==='terms'||h==='support')return policy(h);if(h.startsWith('class/'))return state.user?classView(h.split('/')[1]):login();if(h.startsWith('activate/'))return activate(h.split('/')[1]);if(h.startsWith('assessment-invite/'))return publicAssessmentInvite(h.split('/')[1]);if(h.startsWith('exam/'))return state.user?resumeExam(h.split('/')[1]):login();if(h.startsWith('guest-exam/'))return resumeGuestExam(h.split('/')[1]);if(h.startsWith('verify-certificate/'))return certificateVerifyView(h.split('/').slice(1).join('/'));if(h.startsWith('join/')){if(!state.user)return login();const code=decodeURIComponent(h.split('/')[1]);try{const r=await api('/api/classes/join',{method:'POST',body:JSON.stringify({code})});location.hash=`class/${r.class_id}`}catch(e){slcNotice('Thông báo',e.message)}return}landing()}
let renderPending=null,renderAgain=false;
function render(){
  renderAgain=true;
  if(renderPending)return renderPending;
  renderPending=(async()=>{try{while(renderAgain){renderAgain=false;const hash=location.hash;app.setAttribute('aria-busy','true');try{await renderRoute()}catch(error){if(location.hash===hash)throw error}if(location.hash!==hash)renderAgain=true}}finally{app.removeAttribute('aria-busy');renderPending=null}})();
  return renderPending;
}
window.addEventListener('hashchange' ,()=>{Promise.resolve(render()).catch(showBootstrapError)});
function showBootstrapError(error){
  console.error('[SLC bootstrap]',error);
  const target=document.querySelector('#app');
  if(!target)return;
  target.innerHTML=`<main class="startup-error"><section class="startup-error-card"><div class="eyebrow">TRUNG TÂM HỌC TẬP SỐ</div><h1>Trang chưa thể khởi động hoàn chỉnh.</h1><p>Hệ thống đã tải giao diện nhưng một thành phần đang phản hồi không ổn định. Bạn có thể thử tải lại mà không cần thay đổi dữ liệu hay tài khoản.</p><div class="toolbar"><button class="btn primary" id="startupReload">Tải lại trang</button><a class="btn" href="#support">Trung tâm hỗ trợ</a></div><details><summary>Thông tin hỗ trợ</summary><code>${esc(error?.message||'BOOTSTRAP_ERROR')}</code></details></section></main>`;
  document.querySelector('#startupReload')?.addEventListener('click',()=>location.reload());
}
async function bootstrap(){
  // Never keep the root empty while network/API initialization is pending.
  // Render a usable public shell immediately, then hydrate session/config in parallel.
  try{landing()}catch(error){showBootstrapError(error);return}
  const bootFetch=(path,cacheTtl=0)=>api(path,{cacheTtl,timeout:6000});
  try{
    const [setup,site,me]=await Promise.allSettled([
      bootFetch('/api/setup/status'),
      bootFetch('/api/public/site-config',60000),
      bootFetch('/api/auth/me',5000)
    ]);
    if(setup.status==='fulfilled')state.system={initialized:!!setup.value.initialized,schema_ready:setup.value.schema_ready!==false};
    else state.system={initialized:true,schema_ready:true}; // do not block the public UI on an unavailable setup probe
    if(site.status==='fulfilled'){
      state.site=obj(site.value?.settings);
      state.siteAnnouncements=arr(site.value?.announcements);
    }else{state.site={};state.siteAnnouncements=[]}
    if(me.status==='fulfilled'){
      state.user=normalizeUser(me.value?.user);
      state.activeExam=me.value?.active_exam&&typeof me.value.active_exam==='object'?me.value.active_exam:null;
    }else{
      state.user=null;state.activeExam=null;
    }
    if(state.user){
      try{
        const org=await api('/api/organizations/mine',{cacheTtl:10000,timeout:6000});
        state.organizations=normalizeOrganizations(org?.organizations);
        const saved=storageGet('slc_org');
        state.organizationId=state.organizations.some(o=>o.id===saved)?saved:(state.organizations[0]?.id||'sky-first');const current=state.organizations.find(o=>o.id===state.organizationId);if(state.user&&current?.permissions)state.user.permissions=arr(current.permissions);
      }catch{state.organizations=[];state.organizationId='sky-first'}
    }else{state.organizations=[]}
    await render();
  }catch(error){showBootstrapError(error)}
}
window.addEventListener('error',event=>{
  if(!event?.error)return;
  console.error('[SLC runtime]',event.error);
  if(document.querySelector('#app .startup-shell'))showBootstrapError(event.error);
});
window.addEventListener('unhandledrejection',event=>{
  console.error('[SLC promise]',event.reason);
  if(document.querySelector('#app .startup-shell'))showBootstrapError(event.reason instanceof Error?event.reason:new Error(String(event.reason||'UNHANDLED_PROMISE')));else if(!document.querySelector('.slc-modal-backdrop'))slcNotice('Chưa thể hoàn tất thao tác',event.reason?.message||'Có sự cố kết nối. Vui lòng thử lại.');
});
bootstrap();
